export const ERROR_CODES = [
  'INVALID_STAGE_ACTION',
  'INVALID_TRANSITION',
  'MISSING_REQUIRED_INPUT',
  'STALE_LEASE',
  'LEASE_EXPIRED',
  'LEASE_MISMATCH',
  'PENDING_CHANGE_CONFLICT',
  'SCHEMA_VALIDATION_FAILED',
  'RUNTIME_VALIDATION_FAILED',
  'CLEANUP_TIMEOUT',
  'DEPENDENCY_FAILED',
  'SESSION_NOT_FOUND',
  'WORK_ITEM_NOT_FOUND',
  'UNSUPPORTED_FRAMEWORK',
  'UNKNOWN_DESIGN_SYSTEM',
  'DESTINATION_NOT_EMPTY',
  'SCAFFOLD_FAILED',
  'SOURCE_CONTEXT_INVALID',
  'SOURCE_CONTEXT_TOO_LARGE',
  'VARIANT_NOT_EDITABLE',
  'VARIANT_QA_FAILED',
  'VARIANT_VERIFICATION_UNAVAILABLE',
] as const;

export type ErrorCode = (typeof ERROR_CODES)[number];

export class AgentVariantsError extends Error {
  readonly code: ErrorCode;
  readonly detail: string;

  constructor(code: ErrorCode, message: string) {
    super(`[${code}] ${message}`);
    this.code = code;
    this.detail = message;
    this.name = 'AgentVariantsError';
  }
}
